"""OpenAPI `links`: generated by convention, plus a few written on the route."""

import re
from typing import Any

import pytest

from app.entrypoints.api import create_app

_POINTER = re.compile(r"^\$response\.body#((?:/[^/]+)+)$")


@pytest.fixture(scope="module")
def schema() -> dict[str, Any]:
    """The app's OpenAPI document."""
    return create_app().openapi()


def _operations(schema: dict[str, Any]) -> dict[str, dict[str, Any]]:
    return {
        op["operationId"]: op
        for item in schema["paths"].values()
        for op in item.values()
        if isinstance(op, dict)
    }


def _links(schema: dict[str, Any]) -> list[tuple[str, str, str, dict[str, Any]]]:
    found = []
    for op_id, op in _operations(schema).items():
        for status, response in op["responses"].items():
            for name, link in response.get("links", {}).items():
                found.append((op_id, status, name, link))
    return found


def _resolve(schema: dict[str, Any], node: dict[str, Any]) -> dict[str, Any]:
    while "$ref" in node:
        node = schema["components"]["schemas"][node["$ref"].rsplit("/", 1)[-1]]
    return node


def _body_schema(schema: dict[str, Any], op_id: str, status: str) -> dict[str, Any]:
    response = _operations(schema)[op_id]["responses"][status]
    body: dict[str, Any] = response["content"]["application/json"]["schema"]
    return body


def _follow(schema: dict[str, Any], node: dict[str, Any], pointer: str) -> None:
    """Walk a JSON pointer through a schema, failing if a step does not exist."""
    for step in pointer.strip("/").split("/"):
        node = _resolve(schema, node)
        if step.isdigit():
            assert node["type"] == "array", pointer
            node = node["items"]
        else:
            assert step in node["properties"], pointer
            node = node["properties"][step]


def test_links_exist(schema: dict[str, Any]) -> None:
    """Links are generated across the API."""
    assert len(_links(schema)) > 20


def test_every_link_targets_a_real_operation_and_parameter(
    schema: dict[str, Any],
) -> None:
    """Each link names an existing operation and fills all its path parameters."""
    operations = _operations(schema)
    for op_id, _status, name, link in _links(schema):
        target = operations[link["operationId"]]
        declared = {p["name"] for p in target.get("parameters", [])}
        assert set(link["parameters"]) <= declared, (op_id, name)
        path_params = {p["name"] for p in target["parameters"] if p["in"] == "path"}
        assert path_params <= set(link["parameters"]), (op_id, name)


def test_every_expression_names_a_field_of_the_response(
    schema: dict[str, Any],
) -> None:
    """Each runtime expression points at a field in the response schema."""
    for op_id, status, name, link in _links(schema):
        for expression in link["parameters"].values():
            match = _POINTER.match(expression)
            assert match, (op_id, name, expression)
            _follow(schema, _body_schema(schema, op_id, status), match.group(1))


def test_conventional_links_are_named_after_the_target(schema: dict[str, Any]) -> None:
    """Generated links are named after the target operation."""
    links = {
        name: link for op_id, _, name, link in _links(schema) if op_id == "create_node"
    }
    assert links["GetNode"] == {
        "operationId": "get_node",
        "parameters": {"node_id": "$response.body#/id"},
        "description": "Get node with the id from this response.",
    }
    assert set(links) == {"GetNode", "UpdateNode", "DeleteNode"}


def test_list_responses_use_the_first_item(schema: dict[str, Any]) -> None:
    """List responses link through the first item."""
    list_links = next(
        response["links"]
        for op_id, op in _operations(schema).items()
        if op_id == "list_nodes"
        for response in op["responses"].values()
        if "links" in response
    )
    assert list_links["GetNode"]["parameters"] == {"node_id": "$response.body#/0/id"}
    users = _operations(schema)["list_users"]["responses"]["200"]["links"]
    assert users["UpdateUser"]["parameters"] == {"user_id": "$response.body#/0/id"}


def test_operations_without_a_sibling_get_no_links(schema: dict[str, Any]) -> None:
    """Operations with no id-taking sibling get no links."""
    operations = _operations(schema)
    assert "links" not in operations["create_edges"]["responses"]["201"]
    assert "links" not in operations["get_version"]["responses"]["200"]


def test_personal_export_links_are_written_on_the_routes(
    schema: dict[str, Any],
) -> None:
    """Personal export links come from the route declarations."""
    operations = _operations(schema)
    created = operations["export_user_data"]["responses"]["201"]["links"]
    listed = operations["list_user_exports"]["responses"]["200"]["links"]
    assert created["DownloadExport"]["operationId"] == "download_user_export"
    assert created["DeleteExport"]["operationId"] == "delete_user_export"
    assert listed["DownloadExport"]["parameters"] == {
        "backup_id": "$response.body#/0/id"
    }


def test_token_links_cover_revoke_and_rotate(schema: dict[str, Any]) -> None:
    """Token create and list link to rotate and revoke."""
    operations = _operations(schema)
    for op_id in ("create_api_token", "list_api_tokens"):
        links = next(
            r["links"] for r in operations[op_id]["responses"].values() if "links" in r
        )
        assert {link["operationId"] for link in links.values()} == {
            "rotate_api_token",
            "revoke_api_token",
        }


def test_a_list_of_another_resource_is_not_a_source(schema: dict[str, Any]) -> None:
    """`list_node_media` returns assets, whose ids are not node ids."""
    assert "links" not in _operations(schema)["list_node_media"]["responses"]["200"]
